#[verifier::ensures(result[a.len()] == b)]
#[verifier::ensures(forall(|i: usize| i < a.len() ==> a[i] == old(a)[i]))]
fn append(a: &Vec<i32>, b: i32) -> Vec<i32> {
    // Pre-allocate enough capacity for all existing elements plus one more.
    let mut result = Vec::with_capacity(a.len() + 1);

    // Copy over the existing elements without modifying the original.
    for &item in a.iter() {
        result.push(item);
    }

    // Append the new value.
    result.push(b);

    result
}

